5|export const MAX_EPUB_BYTES = 20 * 1024 * 1024;
6|export const MAX_EPUB_WORDS = 50_000;
7|const MAX_ENTRY_BYTES = 8 * 1024 * 1024;
8|const MAX_INFLATED_BYTES = 60 * 1024 * 1024;
9|
10|export type EpubErrorCode = "not_epub" | "too_large" | "drm" | "unreadable" | "too_long";
11|
12|export class EpubError extends Error {
13|  code: EpubErrorCode;
14|  constructor(code: EpubErrorCode) {
15|    super(code);
16|    this.name = "EpubError";
17|    this.code = code;
18|  }
19|}
20|
21|export const EPUB_ERROR_MESSAGES: Record<EpubErrorCode, string> = {
22|  not_epub: "That doesn't look like an EPUB. Try a file that ends in .epub.",
23|  too_large: "That file is bigger than 20 MB. Most novels are far smaller, so try another edition.",
24|  drm: "This book is copy-protected, so we can't open it. Free classics from Project Gutenberg or Standard Ebooks work well.",
25|  unreadable: "We couldn't read this EPUB. It might be damaged. Try another copy.",
26|  too_long:
27|    "This book is longer than about 200 pages (50,000 words), our limit for now. Pick a shorter one, or try a book from our Library above. Project Gutenberg and Standard Ebooks have plenty of short classics.",
28|};
29|
