43|const COVER_TYPES = new Set(["image/jpeg", "image/png", "image/gif", "image/webp"]);
44|const WORD_RE = /[\p{L}\p{N}]+(?:['’][\p{L}]+)*/gu;
45|
46|// Zip-bomb guard, checked in the inflate filter so big entries never load.
47|export function assertEntrySize(originalSize: number | undefined): void {
