19|const CONTAINER = `<?xml version="1.0"?>
20|<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
21|  <rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles>
22|</container>`;
