29|function epub3(opf: string, extra: Record<string, Uint8Array> = {}): Uint8Array {
30|  return zipSync({
31|    mimetype: strToU8("application/epub+zip"),
32|    "META-INF/container.xml": strToU8(CONTAINER),
33|    "OEBPS/content.opf": strToU8(opf),
34|    ...extra,
35|  });
