49|    <item id="cover" href="cover.png" media-type="image/png" properties="cover-image"/>
50|  </manifest>
51|  <spine><itemref idref="ch1"/><itemref idref="ch2"/><itemref idref="ch3"/></spine>
52|</package>`;
53|
54|const NAV = `<?xml version="1.0" encoding="utf-8"?>
55|<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
56|<head><title>Toc</title></head><body><nav epub:type="toc"><ol>
57|<li><a href="ch1.xhtml">Chapter I. The Cyclone</a></li>
